import json,pathlib,shutil
p=pathlib.Path('public')
date='2026-11-06';base='https://dhar.nic.in/en/'
rows=[]
def fact(field,hi,en,scope,url,period=None,status='verified-source',published=None,conflicts=None,approval='Institutional content approval required'):
 rows.append(dict(field=field,hindiValue=hi,englishValue=en,administrativeScope=scope,sourceUrl=url,publisher='District Administration Dhar' if 'dhar.nic.in' in url else 'Respective official department',publishedDate=published,lastVerified=date,reportingPeriod=period,verificationStatus=status,conflictingSources=conflicts or [],requiredLocalApproval=approval))
for field,hi,en in [('division','इंदौर','Indore'),('area','8,153 वर्ग किमी','8,153 sq km'),('blocks','13 विकासखंड','13 development blocks'),('revenueVillages','1,625 राजस्व ग्राम','1,625 revenue villages')]:fact(field,hi,en,'Dhar district',base+'profile/')
fact('gramPanchayats','764 (विरोधी पुराने स्रोत में 761)','764 (older conflicting source: 761)','Dhar district',base+'profile/',status='conflicting-sources',conflicts=[{'url':base+'about-district/','value':761,'sourceUpdated':'2019-06-13'},{'url':base+'district-election-office-2/','value':764},{'url':base+'subdivision-blocks/','value':'13 rows total 764','sourceUpdated':'2023-07-31'}],approval='Confirm against current LGD and approved district register')
fact('population','21,84,672 (2011 अनंतिम)','2,184,672 (2011 provisional)','Dhar district',base+'profile/','2011 provisional census')
blocks=[('धार','Dhar',52,101),('बदनावर','Badnawar',89,178),('कुक्षी','Kukshi',37,48),('मनावर','Manawar',64,102),('गंधवानी','Gandhwani',69,150),('डही','Dahi',45,61),('धरमपुरी','Dharampuri',51,111),('सरदारपुर','Sardarpur',95,196),('उमरबन','Umarban',61,108),('तिरला','Tirla',52,154),('नालछा','Nalchha',67,192),('बाग','Bagh',48,92),('निसरपुर','Nisarpur',34,63)]
for hi,en,g,v in blocks:fact('block.'+en.lower(),f'{hi}: {g} ग्राम पंचायत, {v} ग्राम',f'{en}: {g} Gram Panchayats, {v} villages','Development block, Dhar district',base+'subdivision-blocks/','Historical table as published 2023-07-31','historical',published='2023-07-31')
fact('villageTotals','ब्लॉक तालिका का योग 1,556; प्रोफाइल में 1,625 राजस्व ग्राम','Block table totals 1,556 villages; profile reports 1,625 revenue villages','Different published village categories / dates',base+'subdivision-blocks/','Historical table 2023-07-31',status='conflicting-sources',conflicts=[{'url':base+'profile/','value':'1,625 revenue villages'}],approval='Reconcile definitions and source dates with local authority')
for k,n in [('PM houses constructed',108917),('SBM rural toilets constructed',377254),('MGNREGA job cards',295592),('Completed Amrut Sarovar works',95),('Completed Pushkar Dharohar works',693)]:fact(k,str(n),str(n),'District-wide cumulative department figures',base+'panchayat-and-rural-development/',status='reporting-period-unspecified')
for k,h,e in [('ceo','श्री अखिलेश कुमार जैन','Shri Akhilesh Kumar Jain'),('officePhone','07292-234709','+91-7292-234709'),('officeEmail','ceozpdha@mp.gov.in','ceozpdha@mp.gov.in')]:fact(k,h,e,'CEO, Zila Panchayat Dhar',base+'divisions/district-officers/',status='published-contact; dynamic recheck required',published='2026-10-30')
fact('legalFramework','मध्य प्रदेश पंचायत राज अधिनियम 1993; 25 जनवरी 1994 से लागू','Madhya Pradesh Panchayat Raj Act 1993; effective 25 January 1994','State of Madhya Pradesh',base+'panchayat-and-rural-development/')
fact('chiefMinister','डॉ. मोहन यादव','Dr. Mohan Yadav','Madhya Pradesh state office','https://epco.mp.gov.in/',status='official-page-verified; dynamic recheck required')
for k in ['officeAddress','officeCoordinates','officeHours','president','gramPanchayatFullDataset','blockBoundaries','projectLevelRecords','advertisingPolicy']:
 fact(k,'सत्यापन / स्वीकृति लंबित','Verification / approval pending','Zila Panchayat Dhar',base+'divisions/district-officers/',status='unverified',approval='Required before official publication; no invented value displayed')
for k,url,status in [('MGNREGA','https://nrega.dord.gov.in/','current-portal-verified; older-FAQ-404'),('PMAY-G','https://pmayg.dord.gov.in/','current-portal-200; local eligibility pending'),('SBM-G','https://swachhbharatmission.ddws.gov.in/','official-summary-verified'),('JJM','https://jaljeevanmission.gov.in/','official-summary-verified'),('DAY-NRLM','https://lokos.dord.gov.in/','current-official-portal-200; local eligibility pending'),('PMKSY','https://pmksy.gov.in/','official-summary-verified')]:
 fact('scheme.'+k,'योजना का स्रोत; वर्तमान स्थानीय पात्रता की पुष्टि आवश्यक',k+' source; confirm current local eligibility','Respective programme; not all directly administered by Zila Panchayat',url,status=status)
json.dump({'verifiedOn':date,'prototype':True,'records':rows},open(p/'evidence-register.json','w'),ensure_ascii=False,indent=2)
json.dump([r for r in rows if r['verificationStatus'] in ['unverified','conflicting-sources','reporting-period-unspecified'] or 'pending' in r['verificationStatus'] or 'historical' in r['verificationStatus']],open('docs/conflict-unverified-register.json','w'),ensure_ascii=False,indent=2)
media=[]
for key,name,author,license,url in [('mandu','Jahaz Mahal, Mandu','Aamin','CC BY-SA 4.0','https://commons.wikimedia.org/wiki/File:JahazMahal.jpg'),('dhar-fort','Dhar Fort','Uchcharia','CC BY-SA 3.0','https://commons.wikimedia.org/wiki/File:Dhar_Fort,_Dhar,_Madhya_Pradesh.jpg'),('dhar-view','Dhar viewed from the fort','Zippymarmalade','Public domain','https://commons.wikimedia.org/wiki/File:Dhar_from_fort.jpg'),('cm','Dr. Mohan Yadav in New Delhi, 30 August 2024','Ministry of Defence / PIB','GODL-India','https://commons.wikimedia.org/wiki/File:Dr._Mohan_Yadav_in_New_Delhi.jpg')]:
 media.append(dict(sourceUrl=url,description=name,photographerAgency=author,licensingStatus=license,creditLine=author+' / Wikimedia Commons / '+license,localFiles=[f'public/images/{key}-640.webp',f'public/images/{key}-1440.webp'],modifications='Resized and WebP conversion; CSS crops in page display',usageApproval='Open licence permits reuse with attribution; official site placement approval pending',verifiedOn=date))
json.dump(media,open('media-manifest.json','w'),indent=2)
shutil.copy2(p/'evidence-register.json','data/evidence-register.json')

media.append({'sourceUrl':'https://epco.mp.gov.in/assets/images/logo.png','description':'Original Madhya Pradesh state emblem','photographerAgency':'Government of Madhya Pradesh / EPCO','licensingStatus':'Official identity asset; no general reuse licence asserted','creditLine':'Government of Madhya Pradesh; official EPCO source','localFiles':['public/images/madhya-pradesh-logo.png'],'modifications':'None; original proportions and colours','usageApproval':'User requested prototype reference; institutional publication authorization pending','verifiedOn':date})
json.dump(media,open('media-manifest.json','w'),ensure_ascii=False,indent=2)
